func (this *GC) FillRoundRectangle(x int32, y int32, width int32, height int32, arcWidth int32, arcHeight int32) {
	if this.Handle == 0 {
		Error(ERROR_GRAPHIC_DISPOSED)
	}
	this.CheckGC(GCFILL)
	var nx int32 = x
	var ny int32 = y
	var nw int32 = width
	var nh int32 = height
	var naw int32 = arcWidth
	var nah int32 = arcHeight
	if nw < 0 {
		nw = 0 - nw
		nx = nx - nw
	}
	if nh < 0 {
		nh = 0 - nh
		ny = ny - nh
	}
	if naw < 0 {
		naw = 0 - naw
	}
	if nah < 0 {
		nah = 0 - nah
	}
	var cairo int64 = this.data.Cairo
	if naw == 0 || nah == 0 {
		gtk.CairoCairo_rectangle(cairo, float64(x), float64(y), float64(width), float64(height))
	} else {
		var naw2 float32 = float32(naw) / 2
		var nah2 float32 = float32(nah) / 2
		var fw float32 = float32(nw) / naw2
		var fh float32 = float32(nh) / nah2
		gtk.CairoCairo_save(cairo)
		gtk.CairoCairo_translate(cairo, float64(nx), float64(ny))
		gtk.CairoCairo_scale(cairo, float64(naw2), float64(nah2))
		gtk.CairoCairo_move_to(cairo, float64(fw-1), float64(0))
		gtk.CairoCairo_arc(cairo, float64(fw-1), float64(1), float64(1), 3.141592653589793+3.141592653589793/2.0, 3.141592653589793*2.0)
		gtk.CairoCairo_arc(cairo, float64(fw-1), float64(fh-1), float64(1), float64(0), 3.141592653589793/2.0)
		gtk.CairoCairo_arc(cairo, float64(1), float64(fh-1), float64(1), 3.141592653589793/2, 3.141592653589793)
		gtk.CairoCairo_arc(cairo, float64(1), float64(1), float64(1), 3.141592653589793, 270.0*3.141592653589793/180.0)
		gtk.CairoCairo_close_path(cairo)
		gtk.CairoCairo_restore(cairo)
	}
	gtk.CairoCairo_fill(cairo)
}

func (this *GC) FixMnemonic(buffer []uint16) int32 {
	var i int32 = 0
	var j int32 = 0
	var mnemonic int32 = -1
	for i < int32(len(buffer)) {
		t310 := i
		i++
		cond309 := buffer[t310]
		t311 := j
		j++
		buffer[t311] = cond309
		if int32((cond309)) == int32('&') {
			if i == int32(len(buffer)) {
				continue
			}
			if int32(buffer[i]) == int32('&') {
				i++
				continue
			}
			if mnemonic == -1 {
				mnemonic = j
			}
			j--
		}
	}
	for j < int32(len(buffer)) {
		t312 := j
		j++
		buffer[t312] = uint16(0)
	}
	return mnemonic
}

